import {createDemoStore,DemoRepository,decimal,add,sub,bishkekDate} from './core.mjs';
import {downloadReport} from './excel.mjs';
import {renderStations,renderStationDetail,renderAccess,renderBrands,handleViewAction} from './views.mjs';

const $=s=>document.querySelector(s);
const KEY='qubat-partner-web-demo-v1';
const today=()=>store?.today||'2026-11-01';
const shift=(date,days)=>new Date(Date.parse(date+'T12:00:00+06:00')+days*86400000).toISOString().slice(0,10);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const decimalDisplay=(v,places=2)=>v==null?'Нет данных':decimal(String(v),places).replace(/\B(?=(\d{3})+(?!\d))/g,' ').replace('.',',');
const money=v=>v==null?'Нет данных':decimalDisplay(v)+' сом';
const energy=v=>v==null?'Нет данных':decimalDisplay(v,3).replace(/,?(0+)$/,'')+' кВт·ч';
const shortMoney=v=>v==null?'Нет данных':decimalDisplay(v);
const dateTime=v=>v?new Intl.DateTimeFormat('ru-RU',{timeZone:'Asia/Bishkek',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'Нет данных';
const dateLabel=v=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',timeZone:'Asia/Bishkek'}).format(new Date(v+'T12:00:00+06:00'));
const paths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',stations:'<rect x="6" y="3" width="11" height="18" rx="2"/><path d="M9 6h5v5H9zM17 7h2l2 3v7a2 2 0 0 1-4 0M9 17h5"/>',reports:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7"/>',finance:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M15 14h6M7 3v2"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-4-5"/>',brands:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M7 5l9 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 4v16M4 12h16"/>',refresh:'<path d="M20 7V2l-4 4a8 8 0 1 0 4 11M20 2h-5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>',moon:'<path d="M21 13a9 9 0 1 1-10-10 7 7 0 0 0 10 10z"/>',pin:'<path d="M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 1 1 14 0z"/><circle cx="12" cy="10" r="2"/>',chart:'<path d="M3 3v18h18M7 15l4-5 4 3 5-8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',warning:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 12l3 3 5-6"/>',edit:'<path d="m15 4 5 5M4 20l2-7L17 2l5 5L11 18z"/>',logout:'<path d="M10 4H4v16h6M10 12h12m-5-5 5 5-5 5"/>'};
const icon=(name,cls='')=>`<svg class="icon ${esc(cls)}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.bolt}</svg>`;
let store,accountId='owner-a';
try {const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.store?.version===2){store=saved.store;accountId=saved.accountId||accountId;}}catch{}
if(!store)store=createDemoStore(today());
let repo;
try {repo=new DemoRepository(store,accountId);} catch {repo=new DemoRepository(store,'owner-a');accountId='owner-a';}
let ui={deductions:['electricity','platformFee','acquiringFee','tax','rent','other'],page:'monitor',stationId:null,period:'7',from:shift(today(),-6),to:today(),stationIdFilter:'',orgId:'',groupId:'',locationId:'',portId:'',customerId:'',operation:'',paymentStatus:'',sessionStatus:'',search:'',reportPage:0,financeMode:'estimate',stationTab:'info',stationFilters:{},accessTab:'members',mobileNav:false};
let modalSubmit=null,toastTimer,searchTimer;
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify({store,accountId:repo.account.id}));}catch{toast('Не удалось сохранить: память браузера заполнена. Скачайте отчёт.');}};
const can=p=>repo.permission(p);
const filters=()=>({from:ui.from,to:ui.to,stationId:ui.stationIdFilter,orgId:ui.orgId,groupId:ui.groupId,locationId:ui.locationId,portId:ui.portId,customerId:ui.customerId,operation:ui.operation,paymentStatus:ui.paymentStatus,sessionStatus:ui.sessionStatus,search:ui.search,deductions:ui.deductions});
const snapshot=()=>can('reports')?repo.report(filters()):null;
const statusLabel={online:'В сети',busy:'Идёт зарядка',offline:'Нет связи',error:'Ошибка',available:'Свободен',fault:'Неисправен',unavailable:'Недоступен',completed:'Завершена',cancelled:'Отменена',paid:'Оплачено · демо',pending:'Ожидает оплаты',refunded:'Возврат · демо',unknown:'Нет данных'};
const badge=(status,stale=false)=>`<span class="status ${stale||status==='offline'?'gray':(['online','available','completed','paid'].includes(status)?'green':['error','fault'].includes(status)?'red':['busy','pending','cancelled','refunded'].includes(status)?'amber':'gray')}">${esc(stale?'Нет свежих данных':statusLabel[status]||status)}</span>`;
const eventTitles={'station.created':'Добавлена новая точка','station.updated':'Изменены параметры точки','station.archived':'Точка перемещена в архив','tariff.updated':'Сохранена новая версия тарифа','finance.month.updated':'Обновлён финансовый месяц','member.invited':'Создан демонстрационный доступ','member.revoked':'Доступ сотрудника отозван','report.exported':'Сформирован отчёт Excel','notifications.updated':'Изменены пороги уведомлений','brand.updated':'Сохранён бренд','discount.updated':'Сохранена скидка','free.granted':'Одобрено право бесплатной зарядки'};
const eventTitle=e=>eventTitles[e.action]||e.title||'Демонстрационное событие';
function eventSummary(e){const row=e.after||{};if(e.action==='report.exported')return `${row.sessions??0} сессий · ${row.filters?.from||''} — ${row.filters?.to||''}`;if(e.action==='tariff.updated'){const last=Array.isArray(row)?row.at(-1):null;return last?`Значение ${last.value}, действует с ${last.effectiveFrom}. Предыдущие версии сохранены.`:'История тарифов обновлена';}if(e.action==='finance.month.updated')return `Месяц ${row.month||''} · ${row.comment||'Расходы и квитанция сохранены'}`;if(e.action?.startsWith('member.'))return row.name||'Демонстрационная учётная запись';if(e.action?.startsWith('station.'))return row.name||e.stationName||'История точки сохранена';if(e.action==='brand.updated'||e.action==='discount.updated'||e.action==='free.granted')return row.name||row.reason||'Изменение с ограничением срока и точек';if(e.action==='notifications.updated')return `Нет связи: ${row.offlineMinutes} мин · низкая мощность: ${row.lowPowerKw} кВт`;return e.message||'Демонстрационная запись';}
const empty=(title='За выбранный период данных не найдено',note='Измените период или фильтры')=>`<div class="empty">${icon('search')}<strong>${esc(title)}</strong>${esc(note)}</div>`;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3800);}
function closeModal(){const el=$('#modal');if(el.open)el.close();modalSubmit=null;}
function openModal({title,body,onSubmit,submitLabel='Сохранить в демо',wide=false}){const el=$('#modal');modalSubmit=onSubmit;el.style.width=wide?'900px':'730px';el.innerHTML=`<form id="modal-form"><header><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-btn" data-action="modal-close" aria-label="Закрыть окно">${icon('close')}</button></header><div class="modal-body">${body}</div><div id="modal-error" role="alert"></div><footer><button type="button" class="btn btn-secondary" data-action="modal-close">${onSubmit?'Отмена':'Закрыть'}</button>${onSubmit?`<button type="submit" class="btn btn-primary">${esc(submitLabel)}</button>`:''}</footer></form>`;if(!el.open)el.showModal();}
async function save(fn){try{await fn();persist();closeModal();render();toast('Изменения сохранены в демонстрационном контуре');return true;}catch(e){const target=$('#modal-error');if(target)target.textContent=e.message;else toast(e.message);return false;}}
function navigate(page,id=null){if(page==='station'&&(ui.page!=='station'||ui.stationId!==id))ui.stationTab='info';ui.page=page;ui.stationId=id;ui.reportPage=0;ui.mobileNav=false;history.replaceState(null,'',`#${page}${id?'/'+encodeURIComponent(id):''}`);render();window.scrollTo({top:0,behavior:'instant'});}
const ctx=()=>({repo,store,ui,esc,money,energy,icon,dateTime,openModal,closeModal,save,navigate,toast});
const names={monitor:['Мониторинг','Обзор вашей зарядной сети'],stations:['Точки','Локации, аппараты и разъёмы'],station:['Карточка станции','Информация и параметры точки'],reports:['Отчёты','Каждая зарядка — в деталях'],finance:['Финансы','Доходы и расходы без смешения'],access:['Доступы','Команда, разрешения и скидки'],brands:['Бренды','Бренды и оборудование вашей сети'],journal:['Журнал событий','История действий и изменений']};
function pageHead(extra=''){const [title,note]=names[ui.page]||names.monitor;return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(note)}</p></div><div class="head-actions">${extra}${can('export')&&['monitor','reports','finance'].includes(ui.page)?`<button class="btn btn-primary" data-action="export">${icon('download','sm')}Скачать Excel</button>`:''}</div></div>`;}
function periodBar(){return `<div class="filters-bar"><div class="period-switch" aria-label="Период отчёта">${[['today','Сегодня'],['7','7 дней'],['month','Месяц'],['previous','Прошлый месяц'],['year','Год']].map(([v,t])=>`<button data-action="period" data-value="${v}" class="${ui.period===v?'active':''}" aria-pressed="${ui.period===v}">${t}</button>`).join('')}</div><div class="row"><select class="scope-select" data-filter="stationIdFilter" aria-label="Станция отчёта"><option value="">Все мои станции</option>${repo.stations().map(s=>`<option value="${esc(s.id)}" ${ui.stationIdFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><div class="date-range">${icon('calendar','sm')}<input aria-label="С даты" type="date" value="${ui.from}" data-filter="from"><span>—</span><input aria-label="По дату" type="date" value="${ui.to}" data-filter="to"></div></div></div>`;}
const kpi=(title,value,unit,symbol,foot)=>`<article class="card kpi"><div class="kpi-top"><span>${title}</span><span class="kpi-symbol">${icon(symbol,'sm')}</span></div><div class="kpi-value mono">${value}<span>${unit}</span></div><div class="kpi-foot">${foot}</div></article>`;
function makeChart(report){if(report&&can('finance')&&report.totals.revenue===null)return empty('Нет подтверждённых платёжных данных','График выручки появится после получения подтверждённых поступлений');if(!report)return empty('Аналитика недоступна','Для этой демо-роли доступен только мониторинг назначенных точек');const finance=can('finance');const daily=new Map();const span=Math.min(365,Math.floor((Date.parse(ui.to)-Date.parse(ui.from))/86400000)+1);const mode=span>40?'month':'day';for(const s of report.sessions){const k=mode==='month'?bishkekDate(s.startedAt).slice(0,7):bishkekDate(s.startedAt);daily.set(k,add(daily.get(k)||'0',finance?sub(s.paid||'0',s.refund||'0'):(s.energy||'0'),finance?2:3));}const keys=[];for(let i=0;i<span;i++){const d=shift(ui.from,i);const k=mode==='month'?d.slice(0,7):d;if(!keys.includes(k))keys.push(k);}const list=keys.slice(-31),vals=list.map(k=>Number(daily.get(k)||0));const max=Math.max(1,...vals)*1.2;const width=620,height=200,left=44,bottom=164,step=(width-left-12)/Math.max(1,list.length);let chart='';for(let i=0;i<4;i++){const y=bottom-i*44;chart+=`<line x1="${left}" y1="${y}" x2="${width}" y2="${y}" stroke="var(--line)" stroke-dasharray="3 5"/><text x="${left-9}" y="${y+3}" text-anchor="end" fill="var(--muted)" font-size="9">${Math.round(max*i/3).toLocaleString('ru-RU')}</text>`;}chart+=list.map((k,i)=>{const h=vals[i]/max*130,w=Math.min(34,step*.52),x=left+i*step+(step-w)/2;const label=mode==='month'?new Date(k+'-15T12:00:00Z').toLocaleDateString('ru-RU',{month:'short'}):dateLabel(k);return `<rect x="${x}" y="${bottom-h}" width="${w}" height="${Math.max(2,h)}" rx="4" fill="${i===list.length-1?'#2b734a':'#98b88a'}"><title>${esc(label)}: ${decimalDisplay(String(vals[i]))} ${finance?'сом':'кВт·ч'} · ДЕМО</title></rect>${(list.length<12||i%Math.ceil(list.length/7)===0||i===list.length-1)?`<text x="${x+w/2}" y="188" fill="var(--muted)" text-anchor="middle" font-size="9">${esc(label)}</text>`:''}`;}).join('');return `<div class="chart-total mono">${shortMoney(finance?report.totals.revenue:report.totals.energy)}<small>${finance?'сом после возвратов':'кВт·ч за период'}</small></div><div class="chart"><svg role="img" aria-label="${finance?'Выручка':'Энергия'} по дням, демонстрационные данные" viewBox="0 0 ${width} ${height}">${chart}</svg></div><div class="chart-footer"><span>${dateLabel(ui.from)} — ${dateLabel(ui.to)} · Asia/Bishkek</span><span>Демонстрационные данные</span></div>`;}
function networkMap(stations){const project=(lat,lon)=>[50+(Number(lon)-69.2)/11.4*450,218-(Number(lat)-39.1)/4.4*180];const cities=[['Бишкек',42.875,74.57],['Ош',40.53,72.80],['Каракол',42.49,78.39],['Токмок',42.84,75.30],['Нарын',41.43,76.0]];return `<div class="map-frame"><svg viewBox="0 0 550 255" role="img" aria-label="Схема расположения назначенных демо-станций в Кыргызстане"><defs><pattern id="map-grid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0v32" fill="none" stroke="#7a947d" stroke-opacity=".08"/></pattern></defs><rect width="550" height="255" fill="url(#map-grid)"/><path d="M47 148 74 130 62 109 104 93 147 92 166 74 215 77 247 49 269 52 304 69 335 54 376 69 412 68 445 87 485 94 503 113 481 143 457 157 419 153 400 173 353 175 320 197 274 200 252 181 230 189 212 174 186 184 160 169 130 183 112 169 86 181 68 170 48 175 36 159z" fill="#d6e1c9" stroke="#bacbb0" stroke-width="1.5"/><path d="m110 140 65-22 73-24 86 19 71-9 57 15M169 142l73 15 61-25 75 20M259 69l-22 38 31 31-10 34" fill="none" stroke="#b6c7a8" stroke-width="1.1" stroke-dasharray="3 4"/><path d="M347 96c24-13 51-3 56 3-1 10-32 17-57 9-6-4-6-8 1-12z" fill="#b5cfd1"/><text x="355" y="119" font-size="8" fill="#759591">Иссык-Куль</text><text class="map-country" x="223" y="154">КЫРГЫЗСТАН</text>${cities.map(([n,lat,lon])=>{const [x,y]=project(lat,lon);return `<text class="map-city" x="${x-15}" y="${y+22}">${n}</text>`;}).join('')}${stations.map(s=>{const [x,y]=project(s.latitude,s.longitude);const color=s.stale||s.status==='offline'?'#9ba898':s.status==='error'?'#c68c67':'#3c8050';return `<g class="map-point" role="button" tabindex="0" aria-label="Открыть ${esc(s.name)}" data-action="nav-station" data-id="${esc(s.id)}"><circle cx="${x}" cy="${y}" r="14" fill="${color}" opacity=".13"/><circle cx="${x}" cy="${y}" r="7.5" fill="${color}" stroke="var(--card)" stroke-width="2.5"/><title>${esc(s.name)} · ${esc(s.stale?'Нет свежих данных':statusLabel[s.status])} · ДЕМО</title></g>`;}).join('')}</svg><div class="map-caption">Схема локаций · ДЕМО · не для навигации</div></div><div class="map-key"><span class="map-legend"><i class="dot" style="background:#3c8050"></i>В сети</span><span class="map-legend"><i class="dot" style="background:#c68c67"></i>Ошибка</span><span class="map-legend"><i class="dot" style="background:#9ba898"></i>Нет связи</span></div>`;}
function renderMonitor(){const stations=repo.stations(),r=snapshot();const online=stations.filter(s=>!s.stale&&!['offline','error'].includes(s.status)).length;const active=repo.activeSessions?.()||[];const power=active.filter(s=>!s.stale).reduce((n,s)=>n+Number(s.powerKw||0),0);const alerts=stations.filter(s=>s.stale||['offline','error'].includes(s.status));return `${pageHead(`<button class="btn btn-secondary" data-action="refresh">${icon('refresh','sm')}Обновить</button>`)}${periodBar()}<div class="kpi-grid">${kpi('Станции в сети',online,`из ${stations.length}`,'stations',`${stations.reduce((n,s)=>n+s.ports.length,0)} разъёмов · ${alerts.length} требуют внимания`)}${kpi('Отпущено энергии',r?decimalDisplay(r.totals.energy,1):'—','кВт·ч','bolt','<strong>За выбранный период</strong> · завершённые сессии')}${can('finance')?kpi('Выручка',r?shortMoney(r.totals.revenue):'—','сом','finance','Оплачено за вычетом возвратов · демо'):kpi('Назначенные точки',stations.length,'точек','shield','Только доступные вашей роли станции')}${kpi('Активные сессии',active.length,'сейчас','chart',`${decimalDisplay(String(power),1)} кВт · тестовая мгновенная мощность`)}</div><div class="dashboard-grid"><section class="card"><div class="section-head"><div><h2>${can('finance')?'Выручка сети':'Энергия сети'}</h2><p>Динамика за выбранный период</p></div><span class="chart-toolbar"><span><i class="legend-dot"></i>${can('finance')?'Выручка':'кВт·ч'}</span></span></div>${makeChart(r)}</section><section class="card"><div class="section-head"><div><h2>География сети</h2><p>Ваши станции в Кыргызстане</p></div><button class="icon-btn" data-action="nav" data-page="stations" aria-label="Открыть все точки">${icon('arrow','sm')}</button></div>${networkMap(stations)}</section></div><div class="bottom-grid"><section class="card"><div class="section-head" style="padding-bottom:18px"><div><h2>Состояние станций</h2><p>${stations.length} точек · ${stations.reduce((n,s)=>n+s.hardwareCount,0)} физических аппаратов</p></div><button class="btn btn-ghost" data-action="nav" data-page="stations">Все точки ${icon('arrow','sm')}</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Станция</th><th>Статус</th><th>Разъёмы</th><th>Мощность</th></tr></thead><tbody>${stations.map(s=>`<tr class="clickable" data-action="nav-station" data-id="${esc(s.id)}"><td><div class="station-cell"><span class="station-mini">${icon('stations','sm')}</span><div><strong>${esc(s.name)}</strong><small>${esc(s.city)} · ${esc(s.id)}</small></div></div></td><td>${badge(s.status,s.stale)}</td><td>${s.ports.filter(p=>p.status==='busy').length} / ${s.ports.length}<div class="progress-bar"><i style="width:${s.ports.filter(p=>p.status==='busy').length/s.ports.length*100}%"></i></div></td><td>${s.stale?'—':decimalDisplay(s.powerKw,1)+' кВт'}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="section-head"><div><h2>Центр внимания</h2><p>Связь, ошибки и изменения</p></div><span class="alert-count">${alerts.length} события</span></div><div class="events">${alerts.map(s=>`<div class="event"><span class="event-symbol warning">${icon('warning','sm')}</span><div><div class="event-text">${esc(s.name)} · ${esc(s.stale?'Нет свежих данных':'Ошибка станции')}</div><div class="event-time">${esc(s.offlineReason||'Тестовое событие оборудования')}<br>Последний сигнал ${dateTime(s.lastSeen)}</div></div></div>`).join('')}${repo.events().slice(0,3).map(e=>`<div class="event"><span class="event-symbol">${icon('check','sm')}</span><div><div class="event-text">${esc(eventTitle(e))}</div><div class="event-time">${esc(e.actorName||e.actor||'ДЕМО')} · ${dateTime(e.at||e.time||e.createdAt)}</div></div></div>`).join('')}${!alerts.length?'<div class="empty">Тестовых тревог по доступным станциям нет</div>':''}</div><div class="chart-footer"><button class="text-link" data-action="nav" data-page="journal">Открыть журнал ${icon('arrow','sm')}</button><span>ДЕМО-контур</span></div></section></div>${active.length?`<section class="card" style="margin-top:23px"><div class="section-head" style="padding-bottom:18px"><div><h2>Активные зарядки</h2><p>Демонстрационные показания · команды оборудованию отключены</p></div><span class="chip">${active.length} сессии</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Сессия / станция</th><th>Порт</th><th>Начало</th><th>кВт</th><th>кВт·ч</th><th>Длительность</th><th>Состояние данных</th></tr></thead><tbody>${active.map(s=>`<tr><td><strong>${esc(s.stationName)}</strong><small>${esc(s.id)}</small></td><td>№${esc(s.portNumber)}</td><td>${dateTime(s.startedAt)}</td><td>${decimalDisplay(s.powerKw,1)}</td><td>${decimalDisplay(s.energy,3)}</td><td>${esc(s.durationMinutes)} мин</td><td>${badge(s.stale?'offline':'busy',s.stale)}<small>${esc(s.source)} · ДЕМО</small></td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function options(items,selected,all){return `<option value="">${all}</option>`+items.map(([v,t])=>`<option value="${esc(v)}" ${selected===v?'selected':''}>${esc(t)}</option>`).join('');}
function extraFilters(){const stations=repo.stations(),unique=(key,label)=>[...new Map(stations.map(s=>[s[key],s[label]])).entries()];return `<details class="filters-details" ${[ui.groupId,ui.locationId,ui.orgId,ui.portId,ui.customerId,ui.operation,ui.paymentStatus,ui.sessionStatus].some(Boolean)?'open':''}><summary>Дополнительные фильтры: локация, разъём, оплата и статус</summary><div class="filter-grid">${[['orgId','Организация',unique('orgId','ownerName'),'Все организации'],['groupId','Группа',unique('groupId','groupName'),'Все группы'],['locationId','Локация',unique('locationId','city'),'Все локации'],['portId','Разъём',stations.flatMap(s=>s.ports.map(p=>[p.id,`${s.name} · №${p.number}`])),'Все разъёмы'],['paymentStatus','Оплата',[['paid','Оплачено'],['pending','Ожидает оплаты'],['refunded','Возврат'],['unknown','Нет данных']],'Все оплаты'],['sessionStatus','Сессия',[['completed','Завершена'],['cancelled','Отменена'],['error','Ошибка']],'Все статусы'],['operation','Тип операции',[['charging','Зарядка']],'Все операции']].map(([key,label,vals,all])=>`<div class="field"><label for="filter-${key}">${label}</label><select id="filter-${key}" data-filter="${key}">${options(vals,ui[key],all)}</select></div>`).join('')}<div class="field"><label for="filter-customerId">ID демо-клиента</label><input id="filter-customerId" data-filter="customerId" placeholder="Все клиенты" value="${esc(ui.customerId)}"></div></div></details>`;}
function renderReports(){if(!can('reports'))return denied();const r=repo.report(filters());const t=r.totals;const pageSize=20,pages=Math.max(1,Math.ceil(r.sessions.length/pageSize));ui.reportPage=Math.min(ui.reportPage,pages-1);const rows=[...r.sessions].sort((a,b)=>ui.sort==='energy'?Number(b.energy)-Number(a.energy):ui.sort==='oldest'?a.startedAt.localeCompare(b.startedAt):b.startedAt.localeCompare(a.startedAt)).slice(ui.reportPage*pageSize,(ui.reportPage+1)*pageSize);return `${pageHead()}${periodBar()}${extraFilters()}<div class="kpi-grid">${kpi('Успешные сессии',t.successful,'сессий','check',`${t.cancelled} отменено · ${t.failed} с ошибкой`)}${kpi('Отпущено энергии',decimalDisplay(t.energy,1),'кВт·ч','bolt',`${t.durationMinutes} минут суммарно`)}${can('finance')?kpi('Начислено',shortMoney(t.charged),'сом','finance','Начисления до возвратов, оплаты — отдельно'):kpi('Клиенты',t.customers,'за период','users','Только демонстрационные ID')}${can('finance')?kpi('Оплачено',shortMoney(t.paid),'сом','check',`Средний тариф: ${shortMoney(t.averageTariff)} сом/кВт·ч`):kpi('Завершено',t.successful,'сессий','chart','Статистика доступных точек')}</div><section class="card"><div class="section-head" style="padding-bottom:18px"><div><h2>История зарядок</h2><p>${r.sessions.length} записей · время по Asia/Bishkek</p></div><select aria-label="Сортировка сессий" data-filter="sort" style="width:150px;font-size:10px"><option value="newest" ${ui.sort!=='oldest'&&ui.sort!=='energy'?'selected':''}>Сначала новые</option><option value="oldest" ${ui.sort==='oldest'?'selected':''}>Сначала старые</option><option value="energy" ${ui.sort==='energy'?'selected':''}>По энергии</option></select></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>ID / станция</th><th>Начало / окончание</th><th>Порт / клиент</th><th>Энергия</th><th>Тариф</th>${can('finance')?'<th>Начислено / оплачено</th><th>Комиссии</th>':''}<th>Статус</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.stationName)}</strong><small>${esc(s.id)}</small><small>${esc(s.locationName)} · ${esc(s.groupName)}</small></td><td>${dateTime(s.startedAt)}<small>${dateTime(s.endedAt)} · ${esc(s.durationMinutes)} мин</small></td><td>№${esc(s.portNumber)}<small>${esc(s.customerName||s.customerId)}</small></td><td class="mono">${decimalDisplay(s.energy,3)} кВт·ч</td><td>${money(s.tariff)}</td>${can('finance')?`<td>${money(s.charged)}<small>${money(s.paid)} · ${esc(s.method||'Нет данных')}</small>${s.refund&&Number(s.refund)>0?`<small>Возврат: ${money(s.refund)}</small>`:''}</td><td>${money(s.platformFee)}<small>Эквайринг: ${money(s.acquiringFee)}</small></td>`:''}<td>${badge(s.status)}<small>${can('finance')?esc(statusLabel[s.paymentStatus]||'Нет данных'):''}</small>${s.error?`<small>${esc(s.error)}</small>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('За выбранный период зарядок не найдено')}<div class="pagination"><span>Показано ${r.sessions.length?ui.reportPage*20+1:0}–${Math.min((ui.reportPage+1)*20,r.sessions.length)} из ${r.sessions.length}</span><div class="actions"><button class="btn btn-secondary" data-action="report-prev" ${ui.reportPage===0?'disabled':''}>Назад</button><span>${ui.reportPage+1} / ${pages}</span><button class="btn btn-secondary" data-action="report-next" ${ui.reportPage+1>=pages?'disabled':''}>Далее</button></div></div></section>`;}
function financeLine(label,value,cls=''){return `<div class="finance-line ${cls}"><span>${label}</span><strong class="mono">${money(value)}</strong></div>`;}
function renderFinance(){if(!can('finance'))return denied();const r=repo.report(filters()),t=r.totals,rows=repo.monthly(filters());const actual=ui.financeMode==='actual';const profit=actual?t.actualProfit:t.estimatedProfit;return `${pageHead()}${periodBar()}<div class="filters-bar"><div class="segmented"><button class="${!actual?'active':''}" data-action="finance-mode" data-value="estimate">Расчётный</button><button class="${actual?'active':''}" data-action="finance-mode" data-value="actual">Фактический</button></div><button class="btn btn-secondary" data-action="profit-formula">${icon('finance','sm')}Статьи расчёта</button></div><p class="finance-mode-note">${actual?'Факт использует введённые квитанции. Если счёт отсутствует, прибыль не подменяется расчётной.':'Расчёт использует энергию сессий и версию закупочного тарифа. Фактические квитанции сохраняются отдельно.'}</p><div class="grid-2" style="margin-bottom:23px"><section class="card"><div class="finance-total"><span class="eyebrow">${actual?'ФАКТИЧЕСКАЯ':'РАСЧЁТНАЯ'} ПРИБЫЛЬ · ДЕМО</span><div class="value mono">${shortMoney(profit)} ${profit==null?'':'<span>сом</span>'}</div><p>${profit==null?'Для части станций не введены подтверждённые счета за электричество':`Маржа: ${decimalDisplay(actual?t.actualMargin??t.margin:t.margin)} % · оплаченная выручка после выбранных расходов`}</p></div><div class="finance-breakdown">${financeLine('Выручка: оплачено − возвраты',t.revenue)}${financeLine('Электричество '+(actual?'по квитанциям':'по тарифу'),actual?t.actualElectricity:t.estimatedElectricity)}${financeLine('Комиссия платформы',t.platformFee)}${financeLine('Эквайринг',t.acquiringFee)}${financeLine('Налог по условиям периода',t.tax)}${financeLine('Аренда',actual?t.actualRent:t.rent)}${financeLine('Прочие расходы',t.other)}${financeLine('Прибыль',profit,'total')}<p class="hint">Формула применяет выбранные статьи расходов. Доля и денежный перевод партнёру учитываются отдельно; выбирайте их осознанно, чтобы не вычесть одну сумму дважды.</p>${financeLine(t.deductions?.includes('partnerShare')?'Доля партнёра · в прибыли':'Доля партнёра · справочно',t.partnerShare)}${financeLine(t.deductions?.includes('reserve')?'Резерв · в прибыли':'Резерв · справочно',t.reserve)}${financeLine(t.deductions?.includes('payout')?'Переводы партнёру · в прибыли':'Переводы партнёру · вне прибыли',t.payout)}</div></section><div><section class="card reconcile"><h2>Акт сверки</h2><p class="muted small" style="margin:6px 0 18px">Начисления и поступления учитываются отдельно</p><div class="reconcile-values"><div>Начислено за сессии<strong>${money(t.charged)}</strong></div><div>Платёжные поступления<strong>${money(t.paid)}</strong></div><div>Возвраты<strong>${money(t.refunds)}</strong></div></div><div class="difference"><span>Начислено, ещё не оплачено</span><strong class="${Number(t.unpaid)>0?'negative':''}">${money(t.unpaid)}</strong></div><p class="hint">${esc(r.reconciliation?.note||'Разница сверки показывается отдельно. Отсутствие подтверждения платежа не считается нулём.')}</p></section><section class="card card-pad" style="margin-top:20px"><h2>Из чего складывается расчёт</h2><div class="finance-line"><span>Энергия завершённых сессий</span><strong>${energy(t.energy)}</strong></div><div class="finance-line"><span>Электричество · расчёт</span><strong>${money(t.estimatedElectricity)}</strong></div><div class="finance-line"><span>Электричество · факт</span><strong>${money(t.actualElectricity)}</strong></div><p class="hint">Ставки электроэнергии, комиссий и налогов имеют дату начала действия. Изменение тарифа не пересчитывает завершённые сессии.</p><button class="btn btn-secondary" style="margin-top:17px" data-action="financial-terms">${icon('calendar','sm')}История условий</button></section></div></div><section class="card"><div class="section-head" style="padding-bottom:18px"><div><h2>Помесячные финансы</h2><p>Квитанции, расходы, прибыль и история изменений</p></div><span class="chip">${rows.length} записей</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Месяц / точка</th><th>Выручка</th><th>Электричество: расчёт / факт</th><th>Аренда / прочее</th><th>Прибыль: расчёт / факт</th><th>Квитанция</th><th></th></tr></thead><tbody>${rows.map(m=>`<tr><td><strong class="month-cell">${esc(m.month)}</strong><small>${esc(m.stationName)}</small></td><td>${money(m.revenue)}</td><td>${money(m.estimatedElectricity)}<small>${money(m.actualElectricity)}</small></td><td>${money(m.rent)}<small>${money(m.other)}</small></td><td>${money(m.estimatedProfit)}<small>${money(m.actualProfit)}</small></td><td>${m.bill?`${badge(m.bill.paid?'paid':'pending')}<small>№${esc(m.bill.number||'—')}</small>`:'<span class="muted">Не внесена</span>'}</td><td><button class="btn btn-ghost" data-action="month-edit" data-station="${esc(m.stationId)}" data-month="${esc(m.month)}">${icon('edit','sm')}Заполнить</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('За этот период финансовых записей нет'):''}</section>`;}
function renderJournal(){const rows=repo.events();return `${pageHead(`<button class="btn btn-secondary" data-action="notifications-settings">${icon('bell','sm')}Пороги уведомлений</button>`)}<div class="banner">${icon('shield')}<div><strong>История сохраняется с автором и временем.</strong><br>Все изменения относятся к локальному демонстрационному контуру.</div></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Дата и время</th><th>Действие</th><th>Объект / изменения</th><th>Автор</th></tr></thead><tbody>${rows.slice(0,100).map(e=>`<tr><td>${dateTime(e.at||e.time||e.createdAt)}</td><td><strong>${esc(eventTitle(e))}</strong></td><td>${esc(e.stationName||e.stationId||e.entityId||e.target||'—')}<small style="white-space:normal;max-width:430px">${esc(eventSummary(e))}</small></td><td>${esc(e.actorName||e.actor||'ДЕМО')}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Пока нет действий','Измените параметры демо-точки или сформируйте Excel'):''}</section>`;}
function denied(){return `<div class="card no-permission">${icon('shield')}<h2>Раздел недоступен этой роли</h2><p>Демо-аккаунт видит только назначенные станции и разрешённые действия.</p><button class="btn btn-secondary" style="margin-top:23px" data-action="roles">Сменить демо-роль</button></div>`;}
function render(){if(!can('view')){$('#app').innerHTML=`<main class="content"><div class="card no-permission">${icon('shield')}<h1>Доступ отозван</h1><p>У этой демонстрационной учётной записи нет действующих назначений.</p><button class="btn btn-primary" data-action="roles" style="margin-top:20px">Выбрать демо-роль</button></div></main>`;return;}const active=document.activeElement;const focusId=active?.id;const caret=active?.selectionStart;let body;try{body=ui.page==='monitor'?renderMonitor():ui.page==='stations'?renderStations(ctx()):ui.page==='station'?renderStationDetail(ctx(),ui.stationId):ui.page==='reports'?renderReports():ui.page==='finance'?renderFinance():ui.page==='access'?renderAccess(ctx()):ui.page==='brands'?renderBrands(ctx()):renderJournal();}catch(e){body=`${pageHead()}<section class="card">${empty('Не удалось показать раздел',e.message)}<div style="text-align:center;padding-bottom:25px"><button class="btn btn-secondary" data-action="refresh">Повторить</button></div></section>`;console.error(e);}
const nav=[['monitor','dashboard','Мониторинг'],['stations','stations','Точки'],...(can('reports')?[['reports','reports','Отчёты']]:[]),...(can('finance')?[['finance','finance','Финансы']]:[]),['access','users','Доступы'],['brands','brands','Бренды'],['journal','clock','Журнал событий']];const account=repo.account;const initials=account.name.split(/\s/).filter(n=>/[А-Яа-яA-Za-z]/.test(n)).slice(0,2).map(n=>n[0].toUpperCase()).join('');const alarms=repo.stations().filter(s=>s.stale||s.status==='error'||s.status==='offline').length;
$('#app').innerHTML=`<div class="shell ${ui.mobileNav?'nav-open':''}"><button class="overlay" data-action="menu" aria-label="Закрыть меню"></button><aside class="sidebar"><a href="#monitor" class="brand" data-action="nav" data-page="monitor"><img src="./favicon.svg" alt=""><div><strong>QUBAT EV</strong><small>PARTNER CABINET</small></div></a><div class="nav-caption">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav class="nav" aria-label="Кабинет партнёра">${nav.map(([p,i,t])=>`<button class="nav-link ${ui.page===p||(p==='stations'&&ui.page==='station')?'active':''}" data-action="nav" data-page="${p}" ${ui.page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${p==='stations'?`<span class="nav-count">${repo.stations().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-note"><div class="env"><i></i>Демонстрационный контур</div>Станции, операции и финансы вымышленные. Подключение оборудования отключено.</div><button class="sidebar-account" data-action="roles"><span class="avatar">${esc(initials)}</span><span style="flex:1;min-width:0"><span class="account-name">${esc(account.name)}</span><span class="account-role" style="display:block">${esc(account.roleLabel)}</span></span>${icon('down','sm')}</button></aside><div class="workspace"><header class="topbar"><div class="row"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><div class="breadcrumbs"><span>Рабочее пространство</span>${icon('chevron','sm')}<strong>Кабинет партнёра</strong></div></div><div class="topbar-actions"><span class="demo-badge">ДЕМО</span><button class="icon-btn" data-action="theme" aria-label="Сменить тему">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-action="notifications" aria-label="Уведомления">${icon('bell')}${alarms?'<i class="notice-dot"></i>':''}</button><button class="topbar-account" data-action="roles" aria-label="Выбрать демо-роль"><span class="avatar">${esc(initials)}</span><span class="account-name">${esc(account.orgName||account.name)}</span>${icon('down','sm')}</button></div></header><main class="content" id="main">${body}<footer class="statusbar"><span>${icon('shield','sm')}QUBAT EV · Кабинет партнёра · ДЕМО</span><span>ДЕМО-снимок ${dateTime(store.now)} · Asia/Bishkek</span></footer></main></div></div>`;
if(focusId){const el=document.getElementById(focusId);if(el){el.focus({preventScroll:true});if(typeof caret==='number'&&el.type!=='date')try{el.setSelectionRange(caret,caret);}catch{}}}}
function changeRole(id){closeModal();repo=new DemoRepository(store,id);accountId=id;ui={...ui,page:'monitor',stationId:null,stationIdFilter:'',orgId:'',groupId:'',locationId:'',portId:'',customerId:'',search:'',reportPage:0,stationFilters:{},mobileNav:false};persist();render();toast('Выбран демонстрационный аккаунт · '+repo.account.roleLabel);}
function roleDialog(){openModal({title:'Демонстрационные роли',body:`<div class="modal-note">Это тестовый кабинет. Выбор роли показывает разные права и станции. Настоящий вход, подтверждение телефона и двухфакторная защита подключаются вместе с сервером.</div>${repo.accounts().map(a=>`<button type="button" class="role-option ${repo.account.id===a.id?'selected':''}" data-action="role-select" data-id="${esc(a.id)}"><span class="avatar">${esc(a.name.slice(0,2))}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.roleLabel)} · ${esc(a.orgName||'Все организации')}</small></span>${repo.account.id===a.id?icon('check'):icon('chevron','sm')}</button>`).join('')}<button type="button" class="btn btn-ghost" style="margin-top:15px" data-action="reset-demo">Восстановить тестовые данные</button>`});}
function monthDialog(stationId,month){const row=repo.monthly({from:month+'-01',to:new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),0)).toISOString().slice(0,10),stationId}).find(r=>r.stationId===stationId&&r.month===month);if(!row)throw Error('Нет строки для выбранного месяца');const bill=row.bill;openModal({title:'Финансы месяца · '+month,body:`<div class="modal-note"><strong>${esc(row.stationName)}</strong><br>Расчёт электричества ${money(row.estimatedElectricity)} сохранится отдельно от квитанции. Все введённые суммы — ДЕМО.</div><div class="form-grid"><div class="field"><label>Электроэнергия по квитанции, сом</label><input name="actualElectricity" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" placeholder="Нет данных" value="${esc(bill?.amount||'')}"></div><div class="field"><label>Номер квитанции</label><input name="billNumber" maxlength="80" value="${esc(bill?.number||'')}"></div><div class="field"><label>Дата документа</label><input type="date" name="billDate" value="${esc(bill?.date||today())}" required></div><div class="field"><label>Показания внешнего счётчика, кВт·ч</label><input name="meterEnergy" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,3})?" placeholder="Нет данных" value="${esc(bill?.meterEnergy||'')}"></div><label class="check-label full"><input type="checkbox" name="billPaid" ${bill?.paid?'checked':''}>Квитанция оплачена · демо</label><div class="field full"><label>Прикрепить квитанцию · демо</label><input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg"><p class="field-help">Сохраняется имя файла. Содержимое не отправляется и не хранится на сервере.${bill?.attachment?.name?' Выбран: '+esc(bill.attachment.name):''}</p></div>${[['rent','Аренда, сом'],['other','Прочие расходы, сом'],['payout','Выплата партнёру, сом']].map(([key,label])=>`<div class="field"><label>${label}</label><input name="${key}" required inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" value="${esc(row[key]||'0.00')}"></div>`).join('')}<div class="field full"><label>Комментарий и причина изменения</label><textarea name="comment" required maxlength="500">${esc(row.comment||'')}</textarea></div></div>`,onSubmit:async data=>{const file=data.get('attachment');if(file?.size>5*1024*1024)throw Error('Размер квитанции — до 5 МБ');const allowed=['application/pdf','image/png','image/jpeg'];if(file?.size&&!allowed.includes(file.type))throw Error('Разрешены PDF, PNG и JPEG');const amount=String(data.get('actualElectricity')||'').trim();const patch={stationId,month,rent:data.get('rent'),other:data.get('other'),payout:data.get('payout'),comment:data.get('comment')};if(amount)patch.bill={amount,number:data.get('billNumber'),date:data.get('billDate'),paid:data.has('billPaid'),meterEnergy:String(data.get('meterEnergy')||'')||null,attachment:file?.size?{name:file.name,size:file.size,type:file.type}:bill?.attachment||null};return save(()=>repo.saveMonthExpense(patch));}});}
function notifications(){const rows=repo.stations().filter(s=>s.stale||['offline','error'].includes(s.status));openModal({title:'Уведомления',body:`<p class="muted small" style="margin-bottom:18px">Тестовые события по доступным станциям. Внешние сообщения не отправляются.</p>${rows.length?rows.map(s=>`<article class="notification"><div class="row">${icon('warning','sm')}<h3>${esc(s.name)}</h3>${badge(s.status,s.stale)}</div><p>${esc(s.offlineReason||'Ошибка демонстрационного оборудования')}</p><p>Последний сигнал: ${dateTime(s.lastSeen)} · ${esc(s.source)}</p></article>`).join(''):empty('Новых тревог нет','В этом демонстрационном наборе назначенные станции работают без тревог')}<button class="btn btn-secondary" data-action="notifications-settings">Пороги и каналы уведомлений</button>`});}
function notificationSettings(){const s=repo.notificationSettings();openModal({title:'Пороги уведомлений · демо',body:`<div class="modal-note">Параметры сохраняются в этом браузере. Email и push-сообщения не отправляются.</div><div class="form-grid">${[['offlineMinutes','Нет связи, минут'],['lowPowerKw','Низкая мощность, кВт'],['longSessionMinutes','Длительная зарядка, минут']].map(([key,label])=>`<div class="field"><label>${label}</label><input name="${key}" type="number" min="1" max="10000" required value="${esc(s[key])}"></div>`).join('')}<label class="check-label"><input type="checkbox" name="email" ${s.email?'checked':''}>Email · демо</label><label class="check-label"><input type="checkbox" name="push" ${s.push?'checked':''}>Push · демо</label></div>`,onSubmit:can('notifications.edit')?data=>save(()=>repo.saveNotifications({offlineMinutes:Number(data.get('offlineMinutes')),lowPowerKw:data.get('lowPowerKw'),longSessionMinutes:Number(data.get('longSessionMinutes')),email:data.has('email'),push:data.has('push')})):null});}
function financialTerms(){const rows=repo.stations().flatMap(s=>(s.tariffs||[]).map(t=>({...t,stationName:s.name})));openModal({title:'История финансовых условий',body:`<p class="muted small" style="margin-bottom:18px">Тариф клиента, электричество, комиссии и налог — независимые условия. Завершённые сессии сохраняют свои значения.</p>${can('tariff.edit')?'<button type="button" class="btn btn-primary" data-action="financial-term-edit" style="margin-bottom:16px">Новая версия условия</button>':''}<div class="table-wrap"><table class="table"><thead><tr><th>Станция</th><th>Условие</th><th>Значение</th><th>С даты</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${esc(t.stationName)}</td><td>${esc(({customer:'Тариф клиента',premium:'Премиум',electricity:'Электроэнергия',platform:'Комиссия платформы',acquiring:'Эквайринг',tax:'Налог',rent:'Аренда',partnerShare:'Доля партнёра',reserve:'Резерв'})[t.kind]||t.kind)}</td><td>${esc(t.value)}</td><td>${esc(t.effectiveFrom)}</td></tr>`).join('')}</tbody></table></div>`});}

function profitFormula(){const choices=[['electricity','Электроэнергия'],['platformFee','Комиссия платформы'],['acquiringFee','Эквайринг'],['tax','Налог'],['rent','Аренда'],['other','Прочие расходы'],['partnerShare','Договорная доля партнёра'],['reserve','Резерв'],['payout','Подтверждённые переводы партнёру']];openModal({title:'Статьи расчёта прибыли',body:`<div class="modal-note">Выручка — оплаченные сессии за вычетом возвратов. Из неё вычитаются только выбранные статьи. Доля партнёра и её выплата могут относиться к одной сумме: не выбирайте обе без соответствующего правила договора.</div><div class="checkbox-grid">${choices.map(([k,t])=>`<label><input type="checkbox" name="deductions" value="${k}" ${ui.deductions.includes(k)?'checked':''}>${t}</label>`).join('')}</div>`,submitLabel:'Применить к отчёту',onSubmit:data=>{ui.deductions=data.getAll('deductions');render();closeModal();toast('Формула применена к экрану и текущей выгрузке Excel');}});}
function financialTermEdit(){const terms=[['electricity','Закупочная цена электричества, сом/кВт·ч'],['platform','Комиссия платформы, %'],['acquiring','Эквайринг, %'],['tax','Налог, %'],['rent','Аренда, сом/месяц'],['partner','Доля партнёра, %'],['reserve','Резерв, %']];openModal({title:'Новая версия финансового условия',body:`<div class="modal-note">Предыдущая версия останется в истории. Завершённые сессии сохранят свои суммы и ставки. Изменяется только локальный демонстрационный журнал.</div><div class="form-grid"><div class="field"><label>Станция</label><select name="stationId">${repo.stations().map(st=>`<option value="${esc(st.id)}">${esc(st.name)}</option>`).join('')}</select></div><div class="field"><label>Условие и база расчёта</label><select name="kind">${terms.map(([k,t])=>`<option value="${k}">${t}</option>`).join('')}</select></div><div class="field"><label>Новое значение</label><input required name="value" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" placeholder="0.00"></div><div class="field"><label>Действует с даты</label><input required type="date" name="effectiveFrom" value="${today()}"></div></div>`,onSubmit:data=>save(()=>repo.updateTariff(data.get('stationId'),{kind:data.get('kind'),value:data.get('value'),effectiveFrom:data.get('effectiveFrom')}))});}

async function action(event){const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;event.preventDefault();try{if(a.startsWith('view-')){await handleViewAction(a,el,ctx());return;}if(a==='nav')navigate(el.dataset.page);else if(a==='nav-station')navigate('station',el.dataset.id);else if(a==='menu'){ui.mobileNav=!ui.mobileNav;render();}else if(a==='modal-close')closeModal();else if(a==='roles')roleDialog();else if(a==='role-select')changeRole(el.dataset.id);else if(a==='theme'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem('qubat-partner-theme',document.documentElement.dataset.theme);render();}else if(a==='refresh'){render();toast('Демонстрационный снимок обновлён');}else if(a==='period'){ui.period=el.dataset.value;ui.to=today();ui.from=ui.period==='today'?ui.to:ui.period==='7'?shift(ui.to,-6):ui.period==='month'?ui.to.slice(0,7)+'-01':ui.to.slice(0,4)+'-01-01';if(ui.period==='previous'){ui.to=shift(today().slice(0,7)+'-01',-1);ui.from=ui.to.slice(0,7)+'-01';}ui.reportPage=0;render();}else if(a==='export'){const report=repo.exportReport?repo.exportReport(filters()):repo.report(filters());if(!can('export'))throw Error('Нет права на экспорт');downloadReport(report);persist();toast('Excel с пятью листами сформирован по текущим фильтрам');}else if(a==='report-next'){ui.reportPage++;render();}else if(a==='report-prev'){ui.reportPage=Math.max(0,ui.reportPage-1);render();}else if(a==='finance-mode'){ui.financeMode=el.dataset.value;render();}else if(a==='month-edit')monthDialog(el.dataset.station,el.dataset.month);else if(a==='financial-terms')financialTerms();else if(a==='profit-formula')profitFormula();else if(a==='financial-term-edit')financialTermEdit();else if(a==='notifications')notifications();else if(a==='notifications-settings')notificationSettings();else if(a==='reset-demo'){openModal({title:'Восстановить демо-данные?',body:'<p>Локальные изменения тарифов, квитанций и доступов будут удалены. Реальное оборудование и деньги не затрагиваются.</p>',submitLabel:'Восстановить',onSubmit:()=>{store=createDemoStore(today());repo=new DemoRepository(store,'owner-a');accountId='owner-a';ui.stationIdFilter='';ui.page='monitor';ui.stationFilters={};persist();render();closeModal();toast('Тестовые данные восстановлены');}});}}catch(e){toast(e.message);console.error(e);}}
document.addEventListener('click',action);
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button][data-action]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('submit',async e=>{if(e.target.id!=='modal-form')return;e.preventDefault();if(!modalSubmit)return;const button=e.target.querySelector('[type=submit]');if(button)button.disabled=true;try{const result=await modalSubmit(new FormData(e.target));if(result!==false)closeModal();}catch(error){$('#modal-error').textContent=error.message;}finally{if(button)button.disabled=false;}});
document.addEventListener('change',e=>{const key=e.target.dataset.filter;if(!key)return;const prev=ui[key];ui[key]=e.target.value;if((key==='from'||key==='to')&&ui.from>ui.to){ui[key]=prev;e.target.value=prev;toast('Дата окончания должна быть не раньше начала');return;}if(key==='from'||key==='to')ui.period='custom';ui.reportPage=0;render();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#modal').addEventListener('cancel',()=>{modalSubmit=null;});
window.addEventListener('hashchange',()=>{const [p,id]=location.hash.slice(1).split('/');if(names[p]){ui.page=p;ui.stationId=id?decodeURIComponent(id):null;render();}});
const [page,id]=location.hash.slice(1).split('/');if(names[page]){ui.page=page;ui.stationId=id?decodeURIComponent(id):null;}
document.documentElement.dataset.theme=localStorage.getItem('qubat-partner-theme')||'light';
render();
